fn collatz(n: u64) -> u32 {
    let mut current = n;
    let mut steps = 0;
    while current != 1 {
        if current % 2 == 0 {
            current /= 2;
        } else {
            current = 3 * current + 1;
        }
        steps += 1;
    }
    steps
}
